const key=id=>"order:detail:"+id;function get(){const id=http.param("id","0");kv.get(key(id)).then(hit=>{if(hit!==null){json.ok({cached:true,data:JSON.parse(hit)});return;}db.query("select id, no, account_id, amount from orders where id = ?",[Number(id)]).then(rows=>{const row=rows[0]??null;kv.set(key(id),JSON.stringify(row)).then(()=>json.ok({cached:false,data:row}));}).catch(e=>json.fail(500,String(e)));});}export default{get};